  const [whole, decimal = ""] = number.split(/[.,]/);
  return Number(whole) * 100 + Number(decimal.padEnd(2, "0"));
}
function zalandoObservation(html, statusCode, link) {
  if (statusCode !== 200 || typeof html !== "string") return null;
  const decode = (text) =>
    text.replace(/&(?:amp|quot|lt|gt|apos|nbsp|#(?:x[0-9a-f]+|\d+));/gi, (entity) => {
      const named = {
        "&amp;": "&",
        "&quot;": '"',
        "&lt;": "<",
        "&gt;": ">",
        "&apos;": "'",
        "&nbsp;": " ",
      };
      if (entity[1] !== "#") return named[entity.toLowerCase()];
      const hex = entity[2].toLowerCase() === "x",
        cp = Number.parseInt(entity.slice(hex ? 3 : 2, -1), hex ? 16 : 10);
      return Number.isSafeInteger(cp) && cp > 0 && cp < 0x110000 && (cp < 0xd800 || cp > 0xdfff)
        ? String.fromCodePoint(cp)
        : "";
    });
  const attrs = (tag) => {
    const values = new Map();
    for (const match of tag.matchAll(/([a-z][\w:-]*)\s*=\s*(?:"([^"]*)"|'([^']*)')/gi)) {
      values.set(match[1].toLowerCase(), decode(match[2] ?? match[3]));
    }
    return values;
  };
  const head = /<head(?:\s[^>]*)?>([\s\S]*?)<\/head>/i.exec(html)?.[1] ?? html;
  for (const match of head.matchAll(/<link\b[^>]*>/gi)) {
    const fields = attrs(match[0]);
    if (fields.get("rel")?.toLowerCase() !== "canonical" || !fields.get("href")) continue;
    try {
      if (productLink(fields.get("href")).split("?")[0] !== link.split("?")[0]) return null;
    } catch {
      return null;
    }
  }
  const prices = new Set();
  for (const match of head.matchAll(/<meta\b[^>]*>/gi)) {
    const fields = attrs(match[0]),
      label = fields.get("name") ?? fields.get("property");
    if (label?.toLowerCase() !== "twitter:data1") continue;
    const contents = fields.get("content")?.trim() ?? "";
    const price = /^(?:CHF\s+(.+)|(.+?)\s+CHF)$/i.exec(contents);
    if (!price) continue;
    const amount = chfCents(price[1] ?? price[2]);
    if (amount === null) return null;
    prices.add(amount);
  }
  const title = /<title(?:\s[^>]*)?>([\s\S]*?)<\/title>/i.exec(head)?.[1];
  const name =
    title &&
    decode(title)
      .replace(/\s*[|–-]\s*Zalando(?:\.ch)?\s*$/i, "")
      .trim()
      .replace(/\s+/g, " ");
  if (
    prices.size !== 1 ||
    !name ||
    name.length > 300 ||
    /[\u0000-\u001f]/.test(name) ||
    /^Zalando(?:\.ch)?$/i.test(name)
  )
    return null;
  return { name, price: [...prices][0] };
}
function observationWrites(product, observation, date) {
  const row = product.row,
    history = product.historyRow;
  return [
    {
      range: "'Links'!C" + row + ":E" + row,
      values: [[observation.price / 100, observation.name, date]],
    },
    {
      range: "'Pricing History'!A" + history + ":F" + history,
      values: [[observation.price / 100, observation.name, product.link, date, product.key, "CHF"]],
    },
  ];
}
function priceNotice(product, observation, recipient) {
  if (observation.price > product.threshold) return null;
  return {
    to: recipient,
    subject: "Price reduction: " + observation.name,
    isHtml: false,
    body:
      observation.name +
      "\nCurrent price: CHF " +
      (observation.price / 100).toFixed(2) +
      "\nAlert threshold: CHF " +
      (product.threshold / 100).toFixed(2) +
      "\n\n" +
      product.link,
  };
}
function sheetWrite(data, spreadsheetId) {
  return {
    spreadsheetId,
    data,
    valueInputOption: "RAW",
    includeValuesInResponse: true,
    responseValueRenderOption: "UNFORMATTED_VALUE",
  };
}
function checkedSheet(reply, spreadsheetId, data) {
  if (
    reply?.spreadsheetId !== spreadsheetId ||
    !Array.isArray(reply.responses) ||
    reply.responses.length !== data.length
  ) {
    throw Error("Google Sheets did not confirm the intended write.");
  }
  const canonical = (value) =>
    typeof value === "string" ? value.replace(/^'([^']+)'!/, "$1!") : "";
  for (const [index, entry] of data.entries()) {
    const result = reply.responses[index];
    if (
      canonical(result.updatedRange) !== canonical(entry.range) ||
      result.updatedRows !== 1 ||
      JSON.stringify(result.updatedData?.values) !== JSON.stringify(entry.values)
    ) {
      throw Error("Google Sheets did not confirm the values in the intended row.");
    }
  }
}
export default async ({ body, statusCode, product, config }, context) => {
  const observation = zalandoObservation(body, statusCode, product.link);
  const result = { link: product.link, status: "price_unavailable" };
  if (!observation) return { result };
  const data = observationWrites(product, observation, config.date);
  const saved = await context.actions.call(
    "googlesheets.update_values_batch",
    sheetWrite(data, config.spreadsheetId),
  );
  checkedSheet(saved, config.spreadsheetId, data);
  result.status = "recorded";
  const mail = priceNotice(product, observation, config.recipient);
  if (!mail) return { result };
  const key =
    "zalando-alert:" +
    createHash("sha256")
      .update(JSON.stringify([config.spreadsheetId, config.recipient, product.key]))
      .digest("hex");
  if (!(await context.state.insert(key, { status: "pending" })))
    return { result: { ...result, status: "earlier_alert" } };
  let sent;
  try {
    sent = await context.actions.call("gmail.send_email", mail);
  } catch {
    return { result: { ...result, status: "email_unconfirmed" } };
  }
  if (typeof sent?.messageId !== "string" || !sent.messageId)
    return { result: { ...result, status: "email_unconfirmed" } };
  await context.state.set(key, { status: "sent", messageId: sent.messageId });
  return { result: { ...result, status: "emailed" } };
};

